INSERT INTO `scenarios` (`id`, `name`, `township`, `scenario`, `base_price`, `base_toll`, `api_station_name`) VALUES
(1, '藍田書院', '南投市', '建於清道光年間的藍田書院，俗稱文昌祠，是南投三大書院中僅存的一座。當你正在欣賞古色古香的濟濟一堂時，院內的老修復師眉頭深鎖地叫住你：『年輕人，這裡有一道關於書院歷史的難題，你能幫忙解開嗎？』', 4500, 450, '南投'),
(2, '中興新村', '南投市', '走入林蔭交織的綠色隧道，中興新村保留了仿英國倫敦「新市鎮」設計的花園城市格局與濃厚的眷村記憶。為了保存這些珍貴史料，當地的數位典藏系統正全速運轉，卻突然閃爍起紅燈，似乎遭遇了邏輯衝突：', 11000, 1100, '南投'),
(3, '武德殿', '南投市', '南投武德殿是一座極具氣勢的仿唐式宏偉建築，過去是日治時期的警察柔道與劍道訓練場。如今這裡轉型為文化展演空間，現場工作人員正為了即將到來的展覽焦頭爛額。系統跳出提示，需要你的協助來梳理動線：', 5500, 550, '南投'),
(4, '世界茶業博覽會', '南投市', '空氣中瀰漫著清雅的茶香，一年一度的世界茶業博覽會正熱烈展開，匯聚了來自各地的頂級茶職人與品茗愛好者。一位茶藝館的文史顧問微笑著向你遞上一杯茶：『品茶如品史，我們正好需要一點跨領域的思維來解開這個結：』', 9000, 900, '南投'),
(5, '南投燈會', '南投市', '夜幕低垂，南投燈會璀璨的燈火點亮了貓羅溪畔，近年結合無人機與原創 IP 的展演更是吸引萬人空巷。正當你準備觀賞主燈秀時，一旁的中控台卻發出異常的警報聲，螢幕上浮現了一個急需排除的邏輯錯誤：', 10000, 1000, '南投'),
(6, '南投配天宮城隍祭', '南投市', '鑼鼓喧天，配天宮的城隍爺暗訪與日巡是南投市一年中最熱鬧的宗教盛事，牛頭馬面與七爺八爺的陣頭威風凜凜。在繞境隊伍旁，一位負責籌備祭典的廟方人員急忙拉住你：『時辰快到了，但這裡的安排出了點狀況，快來幫忙看看！』', 4000, 400, '南投'),
(7, '意麵文化', '南投市', '南投意麵以其不加一滴水、完全用鴨蛋揉製的獨特鹼麵口感聞名，淋上香噴噴的肉燥，是在地人從小吃到大的鄉愁。一家老麵店的自動點餐系統因為瞬間湧入太多訂單而卡死，螢幕上閃爍著需要解決的邏輯問題：', 6000, 600, '南投'),
(8, '南投陶展示館', '南投市', '南投陶擁有兩百多年的悠久歷史，以其獨特的「貼花」與「鑲嵌」技法聞名全台。在展示館內，負責策展的導覽員正對著一堆歷史檔案發愁，藏品資訊實在太過龐雜。系統跳出了一項需要你協助分類的任務：', 5500, 550, '南投'),
(9, '猴探井天空之橋', '南投市', '站上橫跨八卦山深谷的天空之橋，西側的彰化平原與夕陽美景盡收眼底，傳說此地風水極佳，宛如一隻猴子蹲伏俯探深井。一位在橋畔記錄地景的生態學者看著筆電，轉頭向你求助：『這個數據模型的邏輯有點怪，你能幫忙除錯嗎？』', 10500, 1050, '南投'),
(10, '微熱山丘鳳梨文化', '南投市', '八卦山上的紅土孕育了酸甜適中的土鳳梨，成功將傳統農業轉型為揚名國際的甜點品牌，帶動了整個三合院聚落的復興。在熙來攘往的奉茶區旁，生產線的品質監控面板突然顯示異常，需要你運用邏輯來排除障礙：', 11500, 1150, '南投'),
(11, '青山茶區', '南投市', '位於八卦山脈末端的青山茶區，是南投市境內唯一的產茶重鎮，當地茶農利用微氣候優勢種植出甘醇的烏龍與金萱。一位正在巡視茶園的老農無奈地看著自動灌溉系統：『這機器今天不太聽話，年輕人，能幫我看一下這設定問題出在哪嗎？』', 6500, 650, '南投'),
(12, '中興新村省政資料館', '南投市', '省政資料館宛如一座時光膠囊，封存了台灣省政府時期的政經發展檔案與各國外賓贈禮。為確保這些珍貴歷史不被遺忘，後台的數位化建檔系統正在進行大規模數據遷移，卻因負載過高而暫停。你需要解決以下的邏輯衝突：', 5000, 500, '南投'),
(13, '龍泉里洗衣池', '南投市', '聽著潺潺流水聲，龍泉里的百年洗衣池至今仍湧出清澈的自然泉水。這裡不僅是洗滌衣物的地方，更是婆婆媽媽們交流情感的社區情報站。為了將這份獨特的共水文化數位化，記錄系統遇到了資源調度的瓶頸，需要你的協助：', 3500, 350, '南投'),
(14, '中台禪寺', '埔里鎮', '雄偉的中台禪寺高聳入雲，這座由李祖原建築師設計的現代佛教聖地，巧妙融合了中西建築元素與深厚的禪宗美學。在參覽佛教文物時，一位負責維護文獻的法師微笑著向你遞出平板：『歷史脈絡千絲萬縷，或許你的跨領域思維能解開這個結。』', 12000, 1200, '埔里'),
(15, '紙教堂', '埔里鎮', '這座以 58 根巨大紙管建構而成的紙教堂，在 921 大地震後從日本神戶移築至桃米社區，象徵著災後重生與跨國界的大愛。正當你感受這份靜謐與堅韌時，旁邊的生態監測設備卻發出微弱的嗶嗶聲，顯示出一個待解決的邏輯問題：', 9500, 950, '埔里'),
(16, '廣興紙寮手抄紙', '埔里鎮', '水質純淨的埔里是台灣手工造紙的故鄉，廣興紙寮不僅傳承了百年的造紙工藝，更研發出用茭白筍殼製作的「惜物紙」。一位雙手沾滿紙漿的抄紙職人皺著眉頭，朝你招手：『年輕人，配方系統的參數跑掉了，你能幫忙看看嗎？』', 7000, 700, '埔里'),
(17, '祈安清醮', '埔里鎮', '每逢寅年的「祈安清醮」是埔里人最重要的信仰盛事，全鎮茹素的強大凝聚力與壯觀的醮壇令人驚嘆。為了將這每 12 年一次的珍貴陣頭與祭典儀軌完整記錄，後台的資料庫正處於極限運轉狀態，此時出現了一個邏輯錯誤：', 6000, 600, '埔里'),
(18, '龍南天然漆博物館', '埔里鎮', '埔里曾是台灣最重要的漆藝重鎮，龍南博物館內保存了珍貴的割漆工具與歷經繁複工序的精美漆器。現場的典藏管理員正急著將新一批的文物入庫，卻被繁雜的年代與工法標籤搞得暈頭轉向。系統需要你的邏輯協助：', 11000, 1100, '埔里'),
(19, '紹興酒文化 (埔里酒廠)', '埔里鎮', '一靠近埔里酒廠，濃郁的酒香便撲鼻而來。這裡利用著名的愛蘭甘泉釀造出揚名海內外的台灣紹興酒，見證了地方產業的輝煌。一位正在整理酒窖發酵數據的釀酒師推了推眼鏡，向你求助：『溫控數據庫出現了衝突，我們需要你的思維來解開這個結。』', 7500, 750, '埔里'),
(20, '蝴蝶王國復育計畫', '埔里鎮', '台灣曾享有「蝴蝶王國」的美譽，而埔里正是當年的加工與外銷中心。如今，這裡轉向積極的棲地保護與生態復育。在蝴蝶網室旁，環境變數控制系統的指示燈正狂亂閃爍，似乎是溫濕度邏輯出現了問題，需要你立刻排除：', 9000, 900, '埔里'),
(21, '虎頭山飛行傘文化', '埔里鎮', '海拔約 550 公尺的虎頭山擁有絕佳的盆地氣流，是國內外飛行傘好手心中的極限運動聖地。在起飛場旁，一位教練正苦惱地敲打著氣象監測儀：『今天的風切數據有點異常，系統似乎卡在某個迴圈裡了，你能幫忙解開這道題嗎？』', 4500, 450, '埔里'),
(22, '石獅公信仰', '埔里鎮', '埔里街區隱藏著獨特的「石獅公」文化，這些石獅並非守護廟宇，而是先民為了鎮壓水患而設立，見證了早期拓墾與自然搏鬥的歷史。為了數位化保存這些散落各地的石獅座標，地理資訊系統遭遇了運算瓶頸，需要你的邏輯協助：', 8500, 850, '埔里'),
(23, '木生昆蟲博物館', '埔里鎮', '館內收藏了超過十萬件的昆蟲標本，木生昆蟲博物館是世界級的昆蟲寶庫，更見證了台灣從商業捕蝶走向生態保育的歷程。導覽員正忙著為小朋友規劃生態闖關遊戲，但關卡生成的程式碼卻出現了錯誤。系統正在等待你的救援：', 8000, 800, '埔里'),
(24, '大坪頂百香果之鄉', '埔里鎮', '放眼望去，滿山遍野的棚架掛滿了紫紅色的果實。大坪頂是全台最大的百香果產區，當地農民導入了先進的網室栽培與夜間燈照技術。負責產銷履歷的工程師苦笑著向你招手：『物流分配演算法出了一點岔子，你能幫忙看看這錯綜複雜的邏輯嗎？』', 11000, 1100, '埔里'),
(25, '桃米生態村青蛙文化', '埔里鎮', '從 921 震災的廢墟中站起，桃米社區靠著豐富的青蛙與蜻蜓生態，成功轉型為全台知名的生態教育村。在夜間賞蛙的步道入口，遊客總量管制系統的閘門突然卡住，面板上顯示著一段未解的邏輯代碼，需要你在現場立即排解：', 11500, 1150, '埔里'),
(26, '眉溪部落巴宰族祭祖', '埔里鎮', '眉溪部落是台灣少數仍完整保留巴宰族語言與傳統習俗的聚落，每年的銅鑼祭與走鏢活動展現了平埔族群強韌的生命力。一位正在整理族譜與祭典流程的耆老面帶愁容：『年輕人，這些古老資訊在輸入電腦時發生了錯亂，你能幫忙釐清嗎？』', 12000, 1200, '埔里'),
(27, '台灣工藝文化園區', '草屯鎮', '身為國家級的工藝發展核心，園區內匯聚了竹編、漆器、陶藝等大師級作品，是傳統技藝與現代設計對話的殿堂。為了籌備一場大型的跨國線上展覽，伺服器正處於極端高負載的狀態，此時一個核心邏輯模組發生了錯誤：', 5000, 500, '南投'),
(28, '稻草工藝文化節', '草屯鎮', '草屯舊名「草鞋墩」，以盛產草鞋聞名。如今的稻草工藝文化節，將收割後的廢棄稻草編織成巨大的侏羅紀恐龍與地景藝術，徹底實踐循環經濟。現場的資源調度系統因人潮過多而當機，工作人員急忙向你求助：', 5500, 550, '南投'),
(29, '敷榮堂', '草屯鎮', '建於 1928 年的敷榮堂，是草屯望族洪家的傳統閩南式三合院，其精緻的紅磚雕花與彩繪訴說著昔日風華。一位在此進行古蹟測繪的建築系學生苦惱地看著平板：『3D 建模的數據出現了干擾，需要一點跨領域的邏輯思維來解決。』', 6000, 600, '南投'),
(30, '敦和宮銅製財神爺', '草屯鎮', '草屯敦和宮頂樓矗立著一尊高達 162 尺的巨大銅製武財神趙天君，不僅是鎮上的醒目地標，更是各地生意人求財的信仰中心。正當你體驗著鼎盛的香火時，廟方用來處理信眾點燈的數位系統跳出了異常燈號，發現了一個邏輯漏洞：', 6500, 650, '南投'),
(31, '草鞋墩人文觀光夜市', '草屯鎮', '每到週末夜晚，草鞋墩夜市便燈火通明，這裡是南投最具規模的庶民美食天堂，從烤肉香到叫賣聲充滿了鮮活的生命力。管理委員會的廣播系統突然發出雜音，負責人焦急地拿著線路圖跑來：『供電邏輯分配出了問題，快來幫忙看看！』', 7000, 700, '南投'),
(32, '毓繡美術館', '草屯鎮', '隱身在九九峰山腳下的毓繡美術館，以清水模建築與周遭綠意完美融合，是專注於當代寫實藝術的私人美術館。為了維持預約制的高品質參觀體驗，後台的門禁與預約分流系統正處於高負載，此時你發現了一個隱藏的邏輯錯誤：', 8000, 800, '南投'),
(33, '手工麻糬文化', '草屯鎮', '草屯因優質的水源與糯米，孕育出遠近馳名的手工麻糬，其獨特的長條狀與皮薄餡多的口感是旅客必買的伴手禮。在一家知名麻糬老店的後台，自動包裝機的感測器突然失去準度，系統提示需要重新校正邏輯參數：', 8500, 850, '南投'),
(34, '九九峰森林步道', '草屯鎮', '九九峰因地殼變動與雨水沖刷，形成了如同火炎山般鋸齒狀的奇特礫石峰群。走在幽靜的森林步道上，一位林務局的巡山員拿著 GPS 定位儀向你走來：『這些地貌監測數據的演算法似乎有 Bug，你能幫忙解開這個結嗎？』', 9000, 900, '南投'),
(35, '雙冬檳榔地景', '草屯鎮', '七零年代的「雙冬檳榔」曾是台灣經濟奇蹟中獨特的一頁，如今雖然產業轉型，但滿山挺拔的檳榔樹仍記錄了那段產經歷史。在觀察這片特有地景時，路旁的環境微氣候監測站閃爍著警告燈號，顯示有一道邏輯難題待解：', 9500, 950, '南投'),
(36, '紫南宮借發財金', '竹山鎮', '竹山紫南宮以「借發財金」與求「金雞母」聞名全台，香火鼎盛，展現了台灣獨特的土地公信仰與庶民經濟文化。廟方負責處理龐大借還金資料的超級電腦突然亮起紅燈，一位系統維護員焦急地說：『運算邏輯卡住了，快來幫忙排解！』', 5000, 500, '竹山'),
(37, '連興宮', '竹山鎮', '建於清乾隆年間的連興宮，是竹山鎮歷史最悠久的媽祖廟，廟內的黑面二媽與精美的軟身神像見證了前山第一城的開發史。為建立線上數位虛擬廟宇，後台伺服器正處理大量的 3D 點雲資料，卻因邏輯衝突而中斷，需要你的協助：', 5500, 550, '竹山'),
(38, '竹藝編織工藝', '竹山鎮', '竹山顧名思義盛產竹子，這裡的竹編工藝從早期的生活農具，一路進化到如今登上國際展場的精品家飾。在工藝坊內，一台用來切割竹篾的精密雷射儀器因為參數設定錯誤而停機，職人急需你運用邏輯協助排除故障：', 6500, 650, '竹山'),
(39, '小鎮文創 (竹青庭)', '竹山鎮', '竹青庭將廢棄的台西客運站，利用超過五千條在地竹篾編織出宛如巨型竹編洞穴的空間，是青年返鄉創生的極佳典範。一位文史與設計工作者拿著設計圖苦笑：『跨界整合總會遇到奇妙的 Bug，我們正好需要你的跨領域思維來解題。』', 7000, 700, '竹山'),
(40, '大鞍竹海', '竹山鎮', '大鞍林道兩側漫山遍野的孟宗竹林隨風搖曳，宛如武俠電影中的絕美場景，這不僅是觀光勝地，更是水土保持的重要植被。在深山中，一套用於監測土壤含水量的遠端設備失去連線，你在現場發現了傳輸邏輯上的漏洞：', 7500, 750, '竹山'),
(41, '竹山菸草站', '竹山鎮', '日治時期建立的竹山菸草站，曾是收購與集中烘烤菸葉的重要據點。如今保留了獨特的木造建築，轉型為地方文化推廣中心。策展人正為了歷史影像的互動裝置發愁，他招手說：『感測器的觸發邏輯完全亂了，年輕人能幫忙修復嗎？』', 8000, 800, '竹山'),
(42, '社寮地區「丁酒」祭典', '竹山鎮', '每年元宵節過後的農曆正月十六，紫南宮與社寮地區會舉辦盛大的「吃丁酒」習俗，象徵添丁發財與社區分享共榮。由於今年參加人數破紀錄，食材與動線的智慧調度系統不堪負荷而當機。系統急需你的邏輯判斷來解圍：', 9000, 900, '竹山'),
(43, '前山第一城石碑', '竹山鎮', '竹山舊稱「林杞埔」，是漢人開發南投最早的據點，這塊「前山第一城」石碑靜靜地訴說著清代開山撫番的拓荒血淚。一位正在進行數位拓碑的歷史學者看著雜亂的數據庫，尋求你的幫忙：『文獻比對邏輯出錯了，請協助解開這個結。』', 9500, 950, '竹山'),
(44, '集集火車站', '集集鎮', '建於 1930 年代的集集火車站，是台灣少數僅存的純檜木日式車站，見證了當年運輸木材與農產品的黃金歲月。就在你沉浸在鐵道懷舊氛圍時，月台旁的電子號誌控制箱突然發出異常警示，顯示路線調度邏輯出現了危險的衝突：', 5000, 500, '竹山'),
(45, '綠色隧道', '集集鎮', '沿著台 16 線，兩側樹齡超過八十年的老樟樹交織成綿延數公里的綠色隧道，陽光從葉縫中灑落，美不勝收。一位正在檢測樹木健康狀態的樹醫師看著手上的儀器眉頭深鎖：『這棵老樟樹的電阻波形有些奇怪，你能幫忙看看這組數據邏輯嗎？』', 5500, 550, '竹山'),
(46, '樟腦出張所', '集集鎮', '南投曾是名揚國際的「樟腦王國」，集集樟腦出張所是目前台灣保留最完整的日治時期樟腦行政遺構。為了將古老的提煉日誌數位化，後台的資料庫正處於高負載狀態。此時，OCR 辨識系統發生了邏輯錯誤，需要你即刻處理：', 6500, 650, '竹山'),
(47, '軍史公園', '集集鎮', '集集軍史公園內展示著退役的 M41 戰車、F-104 戰機與各式軍武，記錄了早期集集作為國軍重鎮的歷史。現場的擴增實境（AR）導覽系統因為遊客頻繁存取而卡死，負責人急忙調度資源，並懇求你協助修復這個程式邏輯：', 7000, 700, '竹山'),
(48, '明新書院', '集集鎮', '與集集國小比鄰而居的明新書院，是清代地方仕紳為了振興文教而自建的書院，院內的泥塑與彩繪古樸典雅。一位致力於數位修復的文史工作者微笑著望向你：『古蹟修復需要科學與人文的結合，這道演算法的難題就交給你了。』', 7500, 750, '竹山'),
(49, '集集山蕉文化館', '集集鎮', '集集特有的氣候與水土種出了香氣濃郁的「山蕉」，在日治時期更被指定為日本皇室的「御用香蕉」。在了解這段輝煌歷史時，文化館內的互動體驗機台突然當機，螢幕上閃爍著錯誤代碼。你在現場發現了一個邏輯漏洞：', 8000, 800, '竹山'),
(50, '集集攔河堰', '集集鎮', '橫跨濁水溪的集集攔河堰是台灣最大的引水設施，肩負著調度彰化、雲林地區農業與工業用水的重任。在中控室外，一位水利工程師看著水情監測面板直搖頭：『閘門開啟的演算法出現異常，年輕人，你能幫忙看看邏輯哪裡寫錯了嗎？』', 9000, 900, '竹山'),
(51, '大樟樹公信仰', '集集鎮', '樹齡超過七百年的集集大樟樹，枝葉茂密如傘，被當地居民尊奉為「樟樹公」，是在地人乘涼與祈求平安的精神寄託。為了維護這份人文傳承，社區建置的微型環境監控系統正處於異常高負載，出現了必須立刻排除的邏輯錯誤：', 9500, 950, '竹山'),
(52, '日月潭萬人橫泳', '魚池鄉', '每年秋季舉辦的日月潭萬人泳渡，吸引了來自世界各地的游泳好手齊聚一堂，在壯麗的湖光山色中挑戰自我。賽事指揮中心的晶片感測系統突然湧入龐大數據而卡住，工作人員急忙向你呼救，系統需要你的邏輯運算來解圍：', 7000, 700, '埔里'),
(53, '紅玉紅茶 (台茶18號)', '魚池鄉', '由台灣野生山茶與緬甸大葉種配種而成的「台茶 18 號」紅玉紅茶，帶有獨特的薄荷與肉桂香，是享譽國際的頂級茶品。一位品茶師在品鑑大會上微笑看著你：『茶香的層次千絲萬縷，就如同這組品管數據庫，你能用跨領域思維幫忙解開它嗎？』', 7500, 750, '埔里'),
(54, '向山遊客中心', '魚池鄉', '日本建築大師團紀彥設計的向山遊客中心，以清水模的流線型設計完美融入日月潭的湖光山色之中。正當你讚嘆這建築工藝時，負責調節綠建築光影與通風的控制設備閃爍著警告燈號，顯示有一道邏輯問題待你排解：', 8000, 800, '埔里'),
(55, '日月老茶廠', '魚池鄉', '爬滿藤蔓的日月老茶廠，廠內依然轟隆隆地運轉著半世紀前的英國製茶機具，訴說著台灣紅茶外銷的黃金年代。一位老廠長看著新導入的溫濕度物聯網面板，無奈地招手：『年輕人，傳統機器加上新科技反而當機了，你能幫忙看看嗎？』', 9000, 900, '埔里'),
(56, '日月潭文武廟', '魚池鄉', '依山傍水、氣勢磅礴的文武廟，供奉著關聖帝君與孔夫子，廟前的「年梯步道」更是刻滿了 366 天的歷史名人。為了應付春節期間龐大的祈福點燈需求，廟方的數位伺服器正處於臨界點。此時你在後台發現了一個嚴重的邏輯錯誤：', 9500, 950, '埔里'),
(57, '邵族「白鹿傳奇」', '魚池鄉', '相傳邵族先民為了追逐一隻美麗的白鹿，翻山越嶺才發現了魚產豐饒的日月潭（水沙連），從此定居於此。在原住民文化村內，用於播放這段傳說的 3D 全息投影設備卡在了某個畫面，技術人員急忙尋求你的幫助來修復邏輯：', 10000, 1000, '埔里'),
(58, '邵族築箖文化', '魚池鄉', '邵族人利用竹子與木材在潭面上搭建「浮嶼」，發展出獨特的捕魚與水域共生智慧，是日月潭珍貴的人文風景。在研究這種水上建築力學時，旁邊的浮力數據監測儀閃爍著異常燈號，似乎是計算邏輯出了狀況，需要你立即協助：', 11000, 1100, '埔里'),
(59, '頭社活盆地', '魚池鄉', '頭社擁有全台唯一的泥炭土活盆地，人踩在上面土壤會如同波浪般晃動，被稱為「會跳舞的泥土」。一位在當地推廣農耕智慧的職人拿著土壤檢測儀，眉頭深鎖地說：『這數據波動得太不合理了，年輕人，你能用邏輯幫我找出問題在哪嗎？』', 11500, 1150, '埔里'),
(60, '魚池咖啡產業', '魚池鄉', '除了紅茶，魚池近年來在微氣候的優勢下，種植出榮獲精品級認證的高品質咖啡豆，展現了農業的華麗轉型。為了維持烘豆履歷的精準追蹤，雲端資料庫正處於高負載運算，此時一個烘焙曲線的參數引發了系統異常：', 12000, 1200, '埔里'),
(61, '凍頂烏龍茶', '鹿谷鄉', '鹿谷凍頂山是台灣烏龍茶的發源地，這裡獨特的「半發酵」與「慢火炭焙」工序，造就了茶湯金黃、喉韻回甘的極品好茶。在一家老茶行內，新安裝的自動烘焙溫控系統突然失靈，茶師傅急著調度資源，需要你的邏輯思維來搶救這批好茶：', 6500, 650, '鹿谷'),
(62, '冬茶評鑑大賽', '鹿谷鄉', '每年農會舉辦的冬茶評鑑大賽被譽為茶界的「武林大會」，獲得特等獎的茶葉往往身價百倍，象徵著至高的職人榮耀。一位負責評審系統建置的工程師向你微笑：『成績排名的演算法邏輯出現了衝突，我們正好需要一點跨領域的協助。』', 7000, 700, '鹿谷'),
(63, '鳳凰谷鳥園', '鹿谷鄉', '隱身在鹿谷翠綠山林中的鳳凰谷鳥園，不僅飼養了數百種珍禽異鳥，更是一個推廣人與生態共融的絕佳場域。正當你欣賞著五色鳥的身影時，園區內的自動餵食分配系統閃爍著紅燈，顯示邏輯迴圈發生錯誤，亟需你在現場排除：', 7500, 750, '鹿谷'),
(64, '溪頭自然教育園區', '鹿谷鄉', '終年雲霧繚繞的溪頭，擁有大片的柳杉與紅檜林，著名的「大學池」竹橋更是許多人畢業旅行的共同記憶。一位台大實驗林的研究員看著手上的生態監測數據，皺眉說道：『這組樹冠層的碳排吸收數據邏輯怪怪的，你能幫忙解開這道題嗎？』', 8000, 800, '鹿谷'),
(65, '麒麟潭', '鹿谷鄉', '麒麟潭原是百年前先民築壩蓄水而成的灌溉農塘，如今已被翠綠的茶園環繞，波光粼粼，成為美麗的人文水岸地景。為了確保潭水的水質淨化系統穩定運作，後台處理器正極速運轉中，此時卻跳出一個邏輯異常警告：', 9000, 900, '鹿谷'),
(66, '銀杏森林', '鹿谷鄉', '海拔 1500 公尺的大崙山擁有東南亞面積最大的銀杏林，每到秋季，金黃色的銀杏與翠綠烏龍茶樹交織出無與倫比的絕美景觀。現場的氣象微氣候站正因為遊客瘋狂打卡連線而頻寬塞車，系統急需你運用邏輯協助重新分配資源：', 9500, 950, '鹿谷'),
(67, '螢火蟲季活動', '鹿谷鄉', '初夏的鹿谷溪旁，成千上萬的螢火蟲在夜色中閃爍，這是多年來當地居民致力於無農藥與水質保護的驕傲成果。一位生態導覽員拿著故障的報到平板，無奈地望向你：『這報名系統的邏輯錯綜複雜，你能幫我們理出頭緒嗎？』', 10000, 1000, '鹿谷'),
(68, '小半天竹林風景區', '鹿谷鄉', '走進小半天孟宗竹林隧道，宛如步入李安電影《臥虎藏龍》的秘境。這裡的竹產業深深影響了在地的建築、竹編與冬筍飲食文化。在你沉浸於竹林微風時，林務局設置的環境音頻分析儀器發出警報，顯示某個頻率參數邏輯設定錯誤：', 10500, 1050, '鹿谷'),
(69, '茶道表演藝術', '鹿谷鄉', '鹿谷的茶道不僅是沖泡技藝，更是一門結合花藝、器具與靜謐心境的茶席空間藝術。在茶業文化館內，一位茶藝師正對著用來呈現茶席光影的數位燈控台發愁，她連忙招手說：『燈光變化的邏輯跑掉了，年輕人，能幫忙看看嗎？』', 11000, 1100, '鹿谷'),
(70, '龍眼文化節', '中寮鄉', '中寮鄉是台灣龍眼的重要產地，每逢秋收，社區居民便會遵循古法，用龍眼木柴燒烘焙出香氣濃郁的龍眼乾。為了線上推廣這份古早味，農會的電商系統正承受大量湧入的訂單，就在此刻，購物車的庫存邏輯發生了嚴重的衝突：', 3500, 350, '南投'),
(71, '古法龍眼乾焙灶', '中寮鄉', '走近傳統的土角焙灶，老農夫正揮汗如雨地翻動著龍眼，這裡必須三天三夜不斷火燻焙，才能成就頂級的桂圓肉。現場用來監控柴燒溫度的物聯網模組因為高溫而短路重置，資料繁雜卡住。系統急需你的協助來重新設定邏輯：', 4000, 400, '南投'),
(72, '石龍宮泡麵文化', '中寮鄉', '中寮石龍宮供奉的土地公有個全台獨一無二的習俗——信眾皆以「泡麵」祭拜，並在現場大口吃麵，形成奇特的人文信仰景觀。一位民俗學者微笑著望向你：『這信仰背後的大數據很有趣，但資料庫的分析邏輯打結了，你能幫忙解開嗎？』', 4500, 450, '南投'),
(73, '植物染工藝', '中寮鄉', '歷經 921 地震後，中寮婦女利用在地的荔枝葉、墨水樹與洋蔥皮發展出獨具特色的植物染工藝，推廣環境友善美學。在染坊裡，調色配方建檔系統的控制設備突然閃爍著異常燈號，你在現場發現了一個顏色代碼轉換的邏輯問題：', 5000, 500, '南投'),
(74, '龍鳳瀑布空中步道', '中寮鄉', '懸掛於龍瀑布之上的 U 型玻璃空中步道，挑戰著遊客的膽量，也展現了工程設計與自然峽谷景觀的壯麗結合。一位負責橋樑應力監測的工程師看著電腦皺起眉頭：『這組載重數據的邏輯似乎有誤，你能幫忙找出錯誤的變數嗎？』', 6000, 600, '南投'),
(75, '和興有機文化村', '中寮鄉', '和興村是震後自主發起的社區重建典範，村民捨棄農藥，將受創的土地轉型為推廣有機耕作與生態教育的純淨家園。為了確保這份堅持，用於追蹤有機水質的雲端系統正極速運轉，此時你發現感測網路中出現了一個邏輯盲點：', 6500, 650, '南投'),
(76, '仙峰日月洞', '中寮鄉', '仙峰日月洞是一段現代愚公移山的傳奇，一位奇人憑藉一己之力，耗費數十年徒手在堅硬的岩壁上開鑿出深邃的洞穴。館方正試圖用無人機對洞穴進行 3D 測繪，但導航資訊卻因地形干擾而卡住了。系統需要你提供正確的邏輯修正：', 7000, 700, '南投'),
(77, '糯米橋', '國姓鄉', '建於 1940 年的國姓糯米橋，是利用糯米、紅糖、石灰作為黏著劑砌成的三拱石橋，歷經多次風災依然屹立不搖。一位古蹟結構學者微笑著望向你：『古人的智慧與現代力學千絲萬縷，這套結構模擬系統的邏輯出錯了，你能幫忙解開嗎？』', 3500, 350, '埔里'),
(78, '國姓咖啡', '國姓鄉', '國姓鄉九份二山不僅是地震紀念地，如今更轉型為台灣產量最大的精品咖啡產區，帶有獨特的焦糖與核果香氣。在你品嚐手沖咖啡時，吧檯旁的自動烘豆機面板突然閃爍異常警告，顯示豆溫與風門的控制邏輯出現了危險的問題：', 4000, 400, '埔里'),
(79, '鹿神祭', '國姓鄉', '國姓南港村是台灣最大的水鹿養殖區，每年舉辦的「鹿神祭」結合了客家文化與客家大總理祭祀，祈求鹿茸豐收。一位負責祭典儀式數位建檔的村長眉頭深鎖地叫住你：『這流程表輸入電腦後全亂了，你能幫忙釐清這其中的邏輯嗎？』', 5000, 500, '埔里'),
(80, '禪機山仙佛寺', '國姓鄉', '隱身國姓群山中的禪機山仙佛寺，以壯麗的唐風木造建築與日式石燈籠聞名，五百羅漢園區更是充滿祥和的禪意。為了維持寺院線上祈福系統的運作，伺服器正處於高負載狀態。此時，資料流向出現了異常的邏輯中斷：', 5500, 550, '埔里'),
(81, '打石文化', '國姓鄉', '打石是國姓鄉早期的重要產業，糯米橋與當地老屋的石材皆仰賴打石匠師徒手用鋼鑽一寸寸開採，展現極致的職人硬漢精神。一位文史工作者正嘗試用 AI 還原當年的工法，他向你求助：『演算法一直無法閉合，我們需要跨領域的思維來解題。』', 6500, 650, '埔里'),
(82, '北港溪溫泉地熱', '國姓鄉', '北港溪溫泉屬於碳酸氫鈉泉，隱藏在壯麗的峽谷綠林之間，是國姓鄉結合農業與休閒的重要自然資源。正當你享受著山林芬多精時，溫泉水質自動監測站的控制設備突然發出警報，面板上顯示了一段急需破解的邏輯錯誤碼：', 7000, 700, '埔里'),
(83, '受天宮進香期', '名間鄉', '松柏嶺受天宮是全台玄天上帝信仰的總本山，每年進香期高達數千個陣頭湧入，展現了震撼人心的乩童文化與信仰力量。一位負責安排各宮廟進場動線的執事人員滿頭大汗地招手：『隊伍排程邏輯打結了，快來幫忙疏通一下！』', 3500, 350, '南投'),
(84, '松柏嶺茶文化', '名間鄉', '名間鄉的松柏嶺是台灣產量最大的茶區，這裡的八卦山紅土孕育了知名的「松柏長青茶」，並廣泛導入了自動化採茶技術。為了維持龐大的茶葉產銷資料庫運作，系統正全速運轉，此時你卻在後台發現了一個潛在的邏輯危機：', 4000, 400, '南投'),
(85, '生薑與鳳梨文化', '名間鄉', '除了茶葉，名間的紅土地質非常適合種植生薑與鳳梨，一望無際的田園景觀是當地農業經濟的命脈。農會的冷鏈物流中心正急忙調度著各項配送資源，卻因為訂單資訊繁雜而卡住了。系統急需你清晰的邏輯思維來協助排序：', 5000, 500, '南投'),
(86, '震災斜塔遺址', '名間鄉', '921 大地震時，台電的高壓電塔因地層隆起而嚴重傾斜，這座「震災斜塔」被原地保留，成為怵目驚心的防災教育地景。一位地質學者微笑著望向你：『板塊應力的計算模型出了點錯，我們正好需要一點跨領域的思維來解開這個結。』', 5500, 550, '南投'),
(87, '茶香步道', '名間鄉', '漫步在名間的茶香步道，兩旁是修剪得整整齊齊、猶如綠色毛毯般無邊無際的大規模茶園，視覺極為療癒。就在你沉浸於茶鄉微風時，旁邊的自動灑水控制箱閃爍著異常燈號。你在現場發現了一個澆灌時間的邏輯設定問題：', 6500, 650, '南投'),
(88, '萬丹村老樟樹', '名間鄉', '萬丹村有一棵奇特的老樟樹，它因雷擊枯死後，從主幹又長出新枝，形成罕見的「三代同堂」共生奇景，象徵著生命的堅韌。一位樹木保育員看著平板眉頭深鎖：『這組樹幹斷層掃描的數據建構邏輯出錯了，你能幫忙看看嗎？』', 7000, 700, '南投'),
(89, '車埕木業展示館', '水里鄉', '被譽為「最美山城」的車埕，昔日是丹大林區木材的集散地。木業展示館保留了懸吊木材的天車與舊廠房，重現了林業的黃金歲月。為了控制館內的恆溫恆濕系統以保護木造古蹟，後台正處於高負載，此時卻爆發了一個邏輯衝突：', 4500, 450, '竹山'),
(90, '蛇窯陶藝', '水里鄉', '水里蛇窯是台灣現存最古老、最具傳統代表性的柴燒窯。順著山坡而建的狹長窯體，象徵著「火與泥土」的極致藝術傳承。現場的工作人員正準備點火，卻被窯溫預測軟體的報錯卡住了。系統需要你運用邏輯協助排除故障：', 5500, 550, '竹山'),
(91, '二坪山枝仔冰文化', '水里鄉', '來到水里，必定要上二坪山吃一根清涼的「枝仔冰」。這是早期台電大觀發電廠員工利用製冰機做出的平價美味，承載了在地人滿滿的回憶。一位退休的台電老員工笑著望向你：『製冰機的水流控管電路圖有點複雜，你能幫忙解開這道題嗎？』', 6000, 600, '竹山'),
(92, '大觀/明潭發電廠', '水里鄉', '利用日月潭的高低落差，水里的大觀與明潭發電廠是亞洲著名的抽蓄水力發電工程，巨大的引水鋼管令人嘆為觀止。正當你參觀發電模型時，模擬水庫調度的控制面板閃爍著紅色警報，顯示發電邏輯發生了嚴重的異常：', 7000, 700, '竹山'),
(93, '水里木工DIY文化', '水里鄉', '水里將過去發達的林業技術轉化為寓教於樂的木工體驗，讓遊客透過手作板凳與木筷，親身感受木材的溫潤與循環經濟的價值。一位木工職人看著雷射雕刻機的亂碼眉頭深鎖，他連忙招手說：『這圖形路徑的邏輯錯了，你能幫忙修正嗎？』', 7500, 750, '竹山'),
(94, '農產品加工 (梅乾菜/脆梅)', '水里鄉', '水里山區盛產梅子與芥菜，當地客家與農村居民利用醃漬與日曬，製作出風味絕佳的脆梅與梅乾菜，展現了保存食物的古老智慧。為了將這些傳統配方數位化，後台的資料庫正進行繁雜的編譯，此時你發現了一個關鍵的邏輯錯誤：', 8500, 850, '竹山'),
(95, '布農族「八部合音」', '信義鄉', '在信義鄉深山中，布農族人圍成一圈，發出震撼靈魂的「祈禱小米豐收歌」（八部合音），這項無形文化遺產以完美的泛音震驚了全世界。一位錄音師正急著將這些珍貴音軌建檔，卻因為聲波頻率的邏輯重疊而卡住，系統需要你的協助：', 6500, 650, '竹山'),
(96, '打耳祭', '信義鄉', '打耳祭（Malahtangia）是布農族一年中最盛大的祭典，成年男子會帶領男童射擊鹿耳朵，傳承狩獵技巧與家族榮耀。一位致力於原民文化保存的學者微笑著望向你：『祭典的禁忌與流程千絲萬縷，我們正好需要你的跨領域思維來解開這個結。』', 7000, 700, '竹山'),
(97, '望鄉部落「開門見玉山」', '信義鄉', '望鄉部落是全台唯一可以「開門見玉山」的布農族部落。族人對聖山充滿敬畏，家家戶戶的石板牆上都刻畫著祖先的故事。就在你沉浸於這壯麗山景時，旁邊的微型氣象監測站閃爍著異常燈號。你在現場發現了一個數據邏輯問題：', 8000, 800, '竹山'),
(98, '羅娜部落聖誕報佳音', '信義鄉', '全台最大的布農族聚落羅娜村，每逢聖誕節便會舉辦盛大的火把報佳音與詩歌大合唱，將西方宗教與原民熱情完美融合。為了維持當晚全村的燈光秀與廣播同步，後台中控系統正處於高負載狀態，此時出現了一個同步邏輯的錯誤：', 9000, 900, '竹山'),
(99, '玉山嚮導文化', '信義鄉', '信義鄉孕育了無數頂尖的布農族高山嚮導與揹工，他們以超凡的體力與識途智慧，守護著無數攀登玉山的山友安全。在登山口的管制站，入山核對系統正因為龐大的名單而卡住。執勤人員焦急地請求你協助排除這個邏輯障礙：', 9500, 950, '竹山'),
(100, '雙龍瀑布七彩吊橋', '信義鄉', '長達 342 公尺的雙龍七彩吊橋，如同一道彩虹懸掛在深邃的峽谷之上，盡頭是氣勢磅礴的雙龍瀑布。一位負責橋樑安全維護的工程師微笑著望向你：『風切阻力的運算演算法出現了異常，我們正好需要一點跨領域的思維來解題。』', 10000, 1000, '竹山'),
(101, '草坪頭櫻花文化', '信義鄉', '海拔 1300 公尺的草坪頭觀光茶園，每到初春便會綻放滿山的緋寒櫻與吉野櫻，粉紅櫻花與翠綠茶樹交織出絕美的層次。就在你猛按快門時，茶園的自動微霧降溫設備控制箱閃爍著紅燈。你在現場發現了一個設定上的邏輯漏洞：', 11000, 1100, '竹山'),
(102, '清境農場與擺夷文化', '仁愛鄉', '清境不僅有綿羊秀，當年滇緬邊區的「異域孤軍」撤退來此開墾，留下了獨特的雲南擺夷文化與熱鬧的火把節。一位穿著傳統服飾的在地職人眉頭深鎖地叫住你：『年輕人，這個記錄遷徙歷史的互動導覽地圖當機了，你能幫忙看看嗎？』', 7000, 700, '埔里'),
(103, '賽德克族織布工藝', '仁愛鄉', '賽德克族的傳統織布（Puniri）不只是美麗的幾何圖騰，更是族群歷史的密碼與婦女成年的象徵。為了將這些複雜的經緯編織法轉化為數位教材，後台的轉換系統正處於極端高負載狀態，此時你發現了一個致命的迴圈邏輯錯誤：', 8000, 800, '埔里'),
(104, '合歡山暗空公園', '仁愛鄉', '合歡山是全台首座獲得國際認證的「暗空公園」，這裡嚴格管制光害，只為保留最純淨、最璀璨的浩瀚星空。天文台的工作人員正急著調校望遠鏡的追星軌道，卻被龐雜的赤道儀數據卡住了。系統急需你清晰的邏輯來協助除錯：', 9000, 900, '埔里'),
(105, '奧萬大自然教育中心', '仁愛鄉', '以賞楓聞名全台的奧萬大，不僅有壯麗的紅葉地景，更是高山森林保育與環境教育的重要基地。一位林業試驗所的研究員微笑著望向你：『這份生物多樣性的統計模型千絲萬縷，我們正好需要一點跨領域的思維來解開這個結。』', 10000, 1000, '埔里'),
(106, '莫那魯道紀念公園', '仁愛鄉', '位於霧社的莫那魯道紀念公園，莊嚴的抗日紀念碑提醒著後人原住民為了捍衛尊嚴與自由所付出的沉痛代價。就在你沉思這段沉重歷史時，負責播放紀念碑文外語翻譯的數位面板閃爍著異常燈號。你在現場發現了一個語法邏輯問題：', 11000, 1100, '埔里'),
(107, '擺夷飲食文化', '仁愛鄉', '酸辣開胃的雲南大薄片、香氣四溢的錦灑與包包菜，清境的擺夷美食展現了高山地區多元族群融合的特殊風味。一位正忙著備料的餐廳老闆眉頭深鎖，他抬頭看到你連忙招手：『點餐系統的客製化邏輯出錯了，年輕人，能幫忙看看嗎？』', 12000, 1200, '埔里');
